-- The flag "unscalable": a number that is set in stone once rolled. Nothing that changes a line's numbers afterwards
-- touches it: increased effect of modifiers, catalyst quality, enchantment magnitudes, a bundle given at less than its
-- full effect, and whatever is built later that rewrites an item (a Reflecting Mist, a reroll).
--
-- The game's own data has it per stat (Stats IsScalable) and per line (Mods IsUnscalable). These rows are the same
-- flags as rows of the fx tables, and the server reads them here (ModScaling): 2940 stats and 53 lines, exactly the
-- ones the game marks, so nothing changes in play. A new unique's line is made unscalable with a row in fx_lines; a
-- line or a stat that is unscalable is opened up by setting its row to 0. A line's row decides before its stats' rows.
ALTER TABLE fx_stats ADD COLUMN unscalable INTEGER NOT NULL DEFAULT 0 CHECK (unscalable IN (0, 1));
CREATE TABLE fx_lines (
    mod TEXT PRIMARY KEY,
    unscalable INTEGER NOT NULL DEFAULT 0 CHECK (unscalable IN (0, 1)),
    note TEXT
) STRICT;
